import { JobView, isFinished, statusForExit } from "../domain/job";
import { JobViewStore } from "../store/jobViewStore";

/**
 * Folds job events into the read model the console API serves.
 * Events can arrive out of order (the bus delivers control before data; remote runners the network order),
 * so status only moves forward: a finished job is never put back to running by a late event.
 */
export class JobProjection {
  constructor(private readonly store: JobViewStore) {}

  apply(e: JobEvent): void {
    switch (e.kind) {
      case "started": {
        const view = this.store.get(e.jobId) ?? this.blank(e.jobId);
        this.store.put({ ...view, name: e.name, startedAt: e.at });
        return;
      }
      case "timeline": {
        const view = this.store.get(e.jobId) ?? this.blank(e.jobId);
        if (e.seq <= view.seq) return; // stale snapshot
        this.store.put({ ...view, log: e.lines, seq: e.seq });
        return;
      }
      case "closed": {
        const view = this.store.get(e.jobId) ?? this.blank(e.jobId);
        if (isFinished(view)) return; // first exit wins
        this.store.put({ ...view, status: statusForExit(e.exitCode), exitCode: e.exitCode, endedAt: e.at });
        return;
      }
    }
  }

